void insert_polygon_constraints(const std::vector<std::vector<double>>& polygon_coords, Triangulation& triangulation, const Kernel::Plane_3& plane, Triangulation::Face_handle& walk_start) {
    // Iterate over each vertex of the polygon
    for (const auto& vertex : polygon_coords) {
        // Create a Point_3 object from the vertex coordinates
        Kernel::Point_3 point(vertex[0], vertex[1], vertex[2]);

        // Project the point onto the plane
        Kernel::Point_3 projected_point = plane.projection(point);

        // Insert the projected point into the triangulation
        Triangulation::Vertex_handle vertex_handle = triangulation.insert(projected_point, walk_start);

        // Update the walk_start face handle for the next iteration
        walk_start = vertex_handle->face();
    }
}

